export function productFocus(slug: string): PartFocus {
 const source = sourceMedia[slug as keyof typeof sourceMedia];
 const focus = source && focusBySource[source.id];
 if (!focus) throw new Error('Missing object-specific product copy: ' + slug);
 return focus;
}
